<?php

use Dedoc\Scramble\Generator;
use Dedoc\Scramble\Scramble;
use Symfony\Component\Yaml\Yaml;

/**
 * OpenAPI is generated by Scramble from the actual routes/controllers, not
 * hand-maintained — CLAUDE.md requires it "can never silently drift" from
 * the code. This regenerates the spec in-memory and diffs the paths and
 * schemas — the actual contract surface — against the committed
 * docs/openapi.yaml. `info`/`servers` are excluded: they carry
 * environment-specific values (APP_NAME, APP_URL) that legitimately vary
 * between the machine that last ran `scramble:export` and CI, without that
 * being a real contract change.
 */
test('docs/openapi.yaml matches what Scramble generates from the current routes', function () {
    $generator = app(Generator::class);
    $config = Scramble::getGeneratorConfig('default');

    // Round-trip through JSON, same as `scramble:export`, so "empty object"
    // vs "empty array" serialization quirks don't register as false drift.
    $generated = json_decode(json_encode($generator($config)), true);

    $committed = Yaml::parseFile(base_path('docs/openapi.yaml'));

    expect($generated['paths'])->toEqual($committed['paths']);
    expect($generated['components'])->toEqual($committed['components']);
})->skip(fn () => ! file_exists(base_path('docs/openapi.yaml')), 'docs/openapi.yaml has not been generated yet');
